import{z as l,x as i,o as e,c as s,q as B,j as A,D as E,d as n,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"匹配市场的深化","description":"","frontmatter":{"title":"匹配市场的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ct-matching-deep.md","filePath":"econ/ct-matching-deep.md","lastUpdated":1791413859000}'),c={name:"econ/ct-matching-deep.md"};function h(p,a,d,m,C,D){const o=i("Mermaid");return e(),s("div",null,[a[2]||(a[2]=B('<h1 id="匹配市场的深化" tabindex="-1">匹配市场的深化 <a class="header-anchor" href="#匹配市场的深化" aria-label="Permalink to &quot;匹配市场的深化&quot;">​</a></h1><div class="epigraph"><p>稳定不是描述性统计，是市场不散架的工程规范；清台所是它的执行机构。</p><footer>—— 据 Roth, Journal of Political Economy, 1984；Roth and Sotomayor, Two-Sided Matching, 1990 整理</footer></div><p><a href="/econ/ct-auction-theory-deep">上一课</a>把拍卖的四前提拧开，本课换到货币缺席的配置：匹配。<a href="/econ/gale-shapley">Gale–Shapley</a>、<a href="/econ/matching-strategy-proof">策略证明</a>、<a href="/econ/many-to-one-matching">多对一</a>与<a href="/econ/school-choice">学校选择</a>已把 DA 的机制性质写满，宏观一侧的匹配流量归 <a href="/econ/search-matching-dmp">DMP</a>。本课做三件事：把「稳定」读成对时机竞争的防御、把合同与互补性写进匹配、以及量出从定理到清台所的工程距离。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>匹配市场的病不在配错人，在配得不是时候。医学院毕业生提前两年被医院锁定，录取名额在成绩公布前签掉；时机竞争一路前移，直到双方都在信息最少的时刻成交——这就是 unraveling，<a href="/econ/unraveling-lemons">柠檬课序</a>里好车逐级退出是它的价值版，这里是时点版。分散市场的每个局部都想抢跑，抢跑的均衡对所有人都更差。第二个缺口在理论侧：DA 的存在性定理在偏好满足替代性时成立——一家医院把第二名换成第三名后，对原有候选人的兴趣不该下降；互补性（两人必须组队、设备与人配套）会毁掉它。稳定的边界在哪，要用更一般的语言重写。</p><p><span class="marginnote">常见误区：初学者容易把「稳定」读成「配得最合适」。实际上稳定说的是「找不到一对医院与学生互相偏好对方胜过现有配对」——它不承诺匹配质量最高，只承诺没人有动机拆伙私奔。清台所防的正是拆伙：绕开它无利可图，抢跑市场就散了架。</span></p><h3 id="从拒绝链到不动点" tabindex="-1">从拒绝链到不动点 <a class="header-anchor" href="#从拒绝链到不动点" aria-label="Permalink to &quot;从拒绝链到不动点&quot;">​</a></h3><p>时代回应：集中清台所是对 unraveling 的制度解。Roth 在 1984 年把美国医聘的清台所写成实证——NRMP 之所以活下来，恰因它产出的匹配是稳定的：没有一对医院与学生会同时偏好对方胜过现有配对，抢跑因此无利可图，时机竞争被钉住。清台所赢的不是别的算法，是「早签约」这个均衡；稳定性是让参与者愿意放弃抢跑的充分理由。</p><p><span class="marginnote">NRMP 的历次改版是自然实验：规则换向学生求婚、换处理 couples 配对，市场参与率与抢跑市场的复活与否跟着变——定理的工程版本「稳定防抢跑」被反复在场外检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>不动点语言把边界写清。Shapley 与 Scarf 在 1974 年的交换经济里证明：房屋市场（每人持一屋、偏好仅此而已）的核非空，顶点交易循环（TTC）给出核中的配置——<a href="/econ/school-choice">学校选择</a>用过它，谱系上它是核的构造。Kelso 与 Crawford 在 1982 年把 DA 存在性背后的条件提炼成替代性：医院对候选人的需求满足 gross substitutes 时，拒绝链收敛，稳定匹配集存在。Hatfield 与 Milgrom 在 2005 年把拍卖与匹配收进同一张图纸：申请、录取、签合同，稳定匹配是稳定合同集的特例，替代性下集合构成完整格，DA 收敛到格的一端——<a href="/econ/implementability-envelope">可实施性与包络</a>用单调结构删搜索，这里用格结构钉存在性，是同一手法在两个方向的运用。</p>',11)),(e(),A(r,null,{default:E(()=>[t(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RACE%5B%22%E5%88%86%E6%95%A3%E5%B8%82%E5%9C%BA%E6%8A%A2%E8%B7%91%EF%BC%9Aunraveling%22%5D%20--%3E%20CLR%5B%22%E9%9B%86%E4%B8%AD%E6%B8%85%E5%8F%B0%E6%89%80%EF%BC%9A%E7%A8%B3%E5%AE%9A%E5%8C%B9%E9%85%8D%22%5D%0A%20%20CLR%20--%3E%20SUB%7B%22%E6%9B%BF%E4%BB%A3%E6%80%A7%E6%88%90%E7%AB%8B%EF%BC%9F%22%7D%0A%20%20SUB%20--%3E%7C%22%E6%88%90%E7%AB%8B%22%7C%20LAT%5B%22%E7%A8%B3%E5%AE%9A%E9%9B%86%E6%98%AF%E6%A0%BC%EF%BC%8CDA%20%E6%94%B6%E6%95%9B%22%5D%0A%20%20SUB%20--%3E%7C%22%E4%BA%92%E8%A1%A5%E7%A0%B4%E5%9D%8F%22%7C%20GAP%5B%22%E5%AD%98%E5%9C%A8%E6%80%A7%E5%A4%B1%E5%AE%88%EF%BC%8C%E9%A1%BB%E6%94%B9%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20LAT%20--%3E%20INC%7B%22%E5%8F%8C%E8%BE%B9%E6%BF%80%E5%8A%B1%22%7D%0A%20%20INC%20--%3E%7C%22%E6%B1%82%E5%A9%9A%E8%BE%B9%E8%AF%9A%E5%AE%9E%22%7C%20OK%5B%22%E6%B8%85%E5%8F%B0%E6%89%80%E6%95%A2%E4%B8%8A%E8%A1%97%22%5D%0A%20%20INC%20--%3E%7C%22%E4%B8%A4%E8%BE%B9%E9%83%BD%E6%93%8D%E7%BA%B5%22%7C%20FIX%5B%22%E8%BF%91%E4%BC%BC%E4%B8%8D%E5%8F%AF%E6%93%8D%E7%BA%B5%EF%BC%9A%E9%9D%A0%E5%A4%A7%E5%B8%82%E5%9C%BA%E7%A8%80%E9%87%8A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>激励的账在<a href="/econ/matching-strategy-proof">策略证明</a>课已对了一半：DA 对求婚边占优策略诚实，对另一边不行，稳定与双边策略证明不可兼得。深一层的机制是大市场稀释：单个医院操纵名额或排序能改善配对的剖面，在参与者众多、偏好分散的市场里可操纵的剖面占比变小——这是清台所敢在大规模市场上街的理由，也是它最难写进定理的部分。工程侧的约束同样真实：couples 配对破坏替代性，<a href="/econ/many-to-one-matching">农村医院定理</a>锁死名额操纵的下界，缺席与容量谎报要在数据里监控；Roth 与 Peranson 在 1999 年的重设计，就是把这些约束一条条折进算法的现场记录。</p><p><span class="marginnote">替代性是技术条件，不是美学判断：couples 想一起工作、科室要求团队成建制，都是互补。清台所的现实版本在这些地方放弃定理、退回启发式加模拟测试——工程与理论的分工在这里最诚实。</span></p><p><span class="marginnote">直觉类比：DA 的拒绝链像逐家上门的求职——申请人揣着自己的排序单从第一志愿开始投，每轮只有「暂时录取」与「拒绝」两种结果，被拒者降一级再投。它一定会停：每份申请要么占掉一个名额、要么把一个已录取者挤去更低的选择，总数有限；停下时没有任何人想撕毁手里的配对，这就是稳定。</span></p>',4)),(e(),A(r,null,{default:E(()=>[t(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%94%B3%E8%AF%B7%E4%BA%BA%E5%90%91%E5%BD%93%E5%89%8D%E6%9C%80%E9%AB%98%E5%BF%97%E6%84%BF%E6%B1%82%E5%A9%9A%22%5D%20--%3E%20B%7B%22%E5%90%8D%E9%A2%9D%E6%9C%AA%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E6%9A%82%E6%97%B6%E5%BD%95%E5%8F%96%EF%BC%8C%E8%BF%9B%E7%AD%89%E5%BE%85%E5%90%8D%E5%8D%95%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E6%88%96%E6%9B%B4%E4%BC%98%E8%80%85%E5%9C%A8%E5%86%8C%22%7C%20D%5B%22%E5%8C%BB%E9%99%A2%E6%AF%94%E8%BE%83%E6%96%B0%E6%97%A7%E7%94%B3%E8%AF%B7%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%BE%83%E5%B7%AE%E8%80%85%E8%A2%AB%E6%8B%92%E7%BB%9D%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%A2%AB%E6%8B%92%E8%80%85%E9%99%8D%E7%BA%A7%EF%BC%8C%E5%90%91%E4%B8%8B%E4%B8%80%E5%BF%97%E6%84%BF%E6%B1%82%E5%A9%9A%22%5D%0A%20%20F%20--%3E%20A%0A%20%20C%20--%3E%20G%5B%22%E6%97%A0%E4%BA%BA%E5%86%8D%E8%A2%AB%E6%8B%92%EF%BC%9A%E5%8C%B9%E9%85%8D%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>货币一旦进入，问题滑回拍卖与谈判，本课的稳定语言要让位给效率与收入；单边匹配的搜寻摩擦归 <a href="/econ/search-matching-dmp">DMP</a>，那里问的是流量与失业，不是清台所的算法。偏好不完全信息、动态重匹配与合同的再谈判，是仍在打开的分支。口径：稳定是防御性规范，不是福利判据——求婚方最优与接收方最优都在稳定集里，选哪端是分配问题，机制的语言能描述它，不能替市场做价值判断。至此本课程的机制单元走完：下一课收束全程。</p><p><span class="marginnote">数字实例：大市场稀释就是分数被分母吃掉。10 家医院里 1 家谎报容量，可操纵的剖面占比是 10%，操纵值得算计；10 万家参与者的市场里同样一家只占 0.001%，单个操纵者改善配对的概率被人群稀释——定理写不出「没有人操纵」，工程上却足够放心。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稳定的工程含义是防 unraveling：清台所用无利可图的抢跑换时机秩序。</li><li>TTC 是房屋核的构造；替代性决定 DA 稳定集的存在，互补性毁它。</li><li>匹配与合同统一在替代性下的格结构上，拍卖是特例。</li><li>双边策略证明不可兼得，大市场用近似不可操纵补工程信心。</li><li>稳定是防御规范不是福利判据，分配端点由求婚方向选择。</li><li>出处：Gale and Shapley, <em>AMM</em> 1962；Shapley and Scarf, <em>JET</em> 1974；Kelso and Crawford, <em>Econometrica</em> 1982；Roth, <em>JPE</em> 1984；Roth and Peranson, <em>AER</em> 1999；Hatfield and Milgrom, <em>REStud</em> 2005。</li></ul>',5))])}const u=l(c,[["render",h]]);export{_ as __pageData,u as default};
